AP4_Result ReadVisualSampleEntry(AP4_ByteStream& stream) {
    AP4_Result result = ReadSampleEntry(stream);
    if (AP4_FAILED(result)) return result;

    // Read predefined values
    AP4_UI32 predefined1;
    AP4_UI16 predefined2;
    stream.Read(&predefined1, sizeof(predefined1));
    stream.Read(&predefined2, sizeof(predefined2));

    // Read dimensions
    AP4_UI16 width, height;
    stream.Read(&width, sizeof(width));
    stream.Read(&height, sizeof(height));

    // Read resolutions
    AP4_UI16 horiz_resolution, vert_resolution;
    stream.Read(&horiz_resolution, sizeof(horiz_resolution));
    stream.Read(&vert_resolution, sizeof(vert_resolution));

    // Read frame count
    AP4_UI16 frame_count;
    stream.Read(&frame_count, sizeof(frame_count));

    // Read compressor name
    AP4_UI8 compressor_name[32];
    stream.Read(compressor_name, sizeof(compressor_name));
    // Ensure null termination
    compressor_name[sizeof(compressor_name) - 1] = '\0';

    // Read additional depth and predefined values
    AP4_UI16 depth;
    AP4_UI8 additional_predefined;
    stream.Read(&depth, sizeof(depth));
    stream.Read(&additional_predefined, sizeof(additional_predefined));

    return AP4_SUCCESS;
}

